manifests.content:
apiVersion: instancetype.kubevirt.io/v1beta1
kind: VirtualMachineClusterPreference
metadata:
  name: generic-windows
spec:
  annotations:
    descheduler.alpha.kubernetes.io/evict: "true"
  clock:
    preferredClockOffset:
      utc: {}
      #timezone: America/New_York
    preferredTimer:
      hpet:
        present: false
      pit:
        tickPolicy: delay
      rtc:
        tickPolicy: catchup
      hyperv: {}
  cpu:
    preferredCPUTopology: spread   
    spreadOptions:
      across: SocketsCores
      ratio: 4
  devices:
    preferredDiskBus: virtio
    preferredDiskCache: writethrough
    preferredInterfaceModel: virtio
    preferredRng: {}
  features:
    preferredAcpi: {}
    preferredApic: {}
    preferredHyperv:
      reenlightenment: {}
      ipi: {}
      synic: {}
      synictimer: {}
      spinlocks:
        spinlocks: 8191
      reset: {}
      relaxed: {}
      vpindex: {}
      runtime: {}
      tlbflush: {}
      frequencies: {}
      vapic: {}
    preferredPvspinlock: {}
    preferredSmm: {}
  firmware:
    preferredUseEfi: true
    preferredUseSecureBoot: true
  machine:
    preferredMachineType: q35    
  preferredTerminationGracePeriodSeconds: 180
